=== FILE: apb_gpio.v ===
// apb_gpio: APB4 GPIO with edge/level interrupts.
// Implements interface_spec.md per microarchitecture.md.
`default_nettype none

module apb_gpio #(
    parameter ADDR_WIDTH = 8,
    parameter N          = 8
) (
    input  wire                  pclk,
    input  wire                  presetn,
    input  wire [ADDR_WIDTH-1:0] paddr,
    input  wire                  psel,
    input  wire                  penable,
    input  wire                  pwrite,
    input  wire [31:0]           pwdata,
    input  wire [3:0]            pstrb,
    output reg  [31:0]           prdata,
    output wire                  pready,
    output wire                  pslverr,
    input  wire [N-1:0]          gpio_in,
    output wire [N-1:0]          gpio_out,
    output wire [N-1:0]          gpio_oe,
    output wire                  irq
);

    // Bits 0..N-1 set.
    localparam [31:0] PINS = 32'hFFFF_FFFF >> (32 - N);

    localparam [3:0] IDX_DATA_OUT    = 4'd0;
    localparam [3:0] IDX_DIR         = 4'd1;
    localparam [3:0] IDX_DATA_IN     = 4'd2;
    localparam [3:0] IDX_INTR_RISE   = 4'd3;
    localparam [3:0] IDX_INTR_FALL   = 4'd4;
    localparam [3:0] IDX_INTR_HIGH   = 4'd5;
    localparam [3:0] IDX_INTR_LOW    = 4'd6;
    localparam [3:0] IDX_INTR_ENABLE = 4'd7;
    localparam [3:0] IDX_INTR_STATUS = 4'd8;

    // ---------------- APB decode ----------------
    wire        access  = psel & penable;
    wire [3:0]  index   = paddr[5:2];
    wire        aligned = (paddr[1:0] == 2'b00);
    wire        upper0  = (paddr[ADDR_WIDTH-1:6] == {(ADDR_WIDTH-6){1'b0}});
    wire        in_map  = (index <= IDX_INTR_STATUS);
    wire        mapped  = aligned & upper0 & in_map;
    wire        wr      = access & pwrite & mapped;
    wire        rd      = access & ~pwrite & mapped;

    wire [31:0] wmask = {{8{pstrb[3]}}, {8{pstrb[2]}}, {8{pstrb[1]}}, {8{pstrb[0]}}} & PINS;
    wire [31:0] wbits = pwdata & wmask;

    assign pready  = 1'b1;
    assign pslverr = access & (~mapped | (pwrite & (index == IDX_DATA_IN)));

    // ---------------- State ----------------
    reg [31:0] data_out;
    reg [31:0] dir;
    reg [31:0] in_q;
    reg [31:0] in_prev;
    reg [31:0] rise_en;
    reg [31:0] fall_en;
    reg [31:0] high_en;
    reg [31:0] low_en;
    reg [31:0] int_en;
    reg [31:0] status;

    reg [31:0] data_out_d;
    reg [31:0] dir_d;
    reg [31:0] rise_en_d;
    reg [31:0] fall_en_d;
    reg [31:0] high_en_d;
    reg [31:0] low_en_d;
    reg [31:0] int_en_d;
    reg [31:0] status_d;
    reg [31:0] in_ext;

    // gpio_in widened to 32 bits, zeros above N.
    always @* begin
        in_ext        = 32'd0;
        in_ext[N-1:0] = gpio_in;
    end

    // ---------------- Detection ----------------
    wire [31:0] rise     = in_q & ~in_prev;
    wire [31:0] fall     = ~in_q & in_prev;
    wire [31:0] detected = ((rise & rise_en) | (fall & fall_en)
                          | (in_q & high_en) | (~in_q & low_en)) & PINS;
    wire [31:0] clear    = (wr && (index == IDX_INTR_STATUS)) ? wbits : 32'd0;

    // ---------------- Next state ----------------
    always @* begin
        data_out_d = data_out;
        dir_d      = dir;
        rise_en_d  = rise_en;
        fall_en_d  = fall_en;
        high_en_d  = high_en;
        low_en_d   = low_en;
        int_en_d   = int_en;
        // Detection is ORed last: a detection beats a clear.
        status_d   = (status & ~clear) | detected;
        if (wr) begin
            case (index)
                IDX_DATA_OUT:    data_out_d = (data_out & ~wmask) | wbits;
                IDX_DIR:         dir_d      = (dir      & ~wmask) | wbits;
                IDX_INTR_RISE:   rise_en_d  = (rise_en  & ~wmask) | wbits;
                IDX_INTR_FALL:   fall_en_d  = (fall_en  & ~wmask) | wbits;
                IDX_INTR_HIGH:   high_en_d  = (high_en  & ~wmask) | wbits;
                IDX_INTR_LOW:    low_en_d   = (low_en   & ~wmask) | wbits;
                IDX_INTR_ENABLE: int_en_d   = (int_en   & ~wmask) | wbits;
                default: begin end
            endcase
        end
    end

    // ---------------- Registers (synchronous active-low reset) ----------------
    always @(posedge pclk) begin
        if (!presetn) begin
            data_out <= 32'd0;
            dir      <= 32'd0;
            in_q     <= 32'd0;
            in_prev  <= 32'd0;
            rise_en  <= 32'd0;
            fall_en  <= 32'd0;
            high_en  <= 32'd0;
            low_en   <= 32'd0;
            int_en   <= 32'd0;
            status   <= 32'd0;
        end else begin
            data_out <= data_out_d;
            dir      <= dir_d;
            in_q     <= in_ext;
            in_prev  <= in_q;
            rise_en  <= rise_en_d;
            fall_en  <= fall_en_d;
            high_en  <= high_en_d;
            low_en   <= low_en_d;
            int_en   <= int_en_d;
            status   <= status_d;
        end
    end

    // ---------------- Read data ----------------
    always @* begin
        prdata = 32'd0;
        if (rd) begin
            case (index)
                IDX_DATA_OUT:    prdata = data_out;
                IDX_DIR:         prdata = dir;
                IDX_DATA_IN:     prdata = in_q;
                IDX_INTR_RISE:   prdata = rise_en;
                IDX_INTR_FALL:   prdata = fall_en;
                IDX_INTR_HIGH:   prdata = high_en;
                IDX_INTR_LOW:    prdata = low_en;
                IDX_INTR_ENABLE: prdata = int_en;
                IDX_INTR_STATUS: prdata = status;
                default:         prdata = 32'd0;
            endcase
        end
    end

    // ---------------- Outputs ----------------
    assign gpio_out = data_out[N-1:0];
    assign gpio_oe  = dir[N-1:0];
    assign irq      = |(status & int_en);

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: apb_gpio_tb.v ===
`timescale 1ns/1ps
`default_nettype none

module apb_gpio_tb;

    localparam [7:0] A_DOUT = 8'h00;
    localparam [7:0] A_DIR  = 8'h04;
    localparam [7:0] A_DIN  = 8'h08;
    localparam [7:0] A_RISE = 8'h0C;
    localparam [7:0] A_FALL = 8'h10;
    localparam [7:0] A_HIGH = 8'h14;
    localparam [7:0] A_LOW  = 8'h18;
    localparam [7:0] A_EN   = 8'h1C;
    localparam [7:0] A_STAT = 8'h20;

    reg         pclk;
    reg         presetn;
    reg  [7:0]  paddr;
    reg         psel;
    reg         penable;
    reg         pwrite;
    reg  [31:0] pwdata;
    reg  [3:0]  pstrb;
    reg  [7:0]  gin;
    reg  [31:0] gin32;

    wire [31:0] prdata;
    wire        pready;
    wire        pslverr;
    wire [7:0]  gout;
    wire [7:0]  goe;
    wire        irq;

    wire [31:0] prdata32;
    wire        pready32;
    wire        pslverr32;
    wire [31:0] gout32;
    wire [31:0] goe32;
    wire        irq32;

    integer passed;
    integer failed;
    reg [8*64-1:0] nonce;

    apb_gpio #(.ADDR_WIDTH(8), .N(8)) u8 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata), .pready(pready), .pslverr(pslverr),
        .gpio_in(gin), .gpio_out(gout), .gpio_oe(goe), .irq(irq)
    );

    apb_gpio #(.ADDR_WIDTH(8), .N(32)) u32 (
        .pclk(pclk), .presetn(presetn), .paddr(paddr), .psel(psel),
        .penable(penable), .pwrite(pwrite), .pwdata(pwdata), .pstrb(pstrb),
        .prdata(prdata32), .pready(pready32), .pslverr(pslverr32),
        .gpio_in(gin32), .gpio_out(gout32), .gpio_oe(goe32), .irq(irq32)
    );

    initial pclk = 1'b0;
    always #5 pclk = ~pclk;

    // ---------------- Checks ----------------
    task chk;
        input [31:0]     got;
        input [31:0]     exp;
        input [8*24-1:0] what;
        begin
            if (got !== exp) begin
                failed = failed + 1;
                $error("FAIL %0s: got %h expected %h", what, got, exp);
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    task chk1;
        input            got;
        input            exp;
        input [8*24-1:0] what;
        begin
            if (got !== exp) begin
                failed = failed + 1;
                $error("FAIL %0s: got %b expected %b", what, got, exp);
            end else begin
                passed = passed + 1;
            end
        end
    endtask

    // ---------------- APB phases (driven after the falling edge) ----------------
    task apb_setup;
        input [7:0]  a;
        input        w;
        input [31:0] d;
        input [3:0]  s;
        begin
            @(negedge pclk);
            psel = 1'b1; penable = 1'b0; pwrite = w;
            paddr = a; pwdata = d; pstrb = s;
            #1;
            chk (prdata,    32'd0, "setup prdata u8");
            chk1(pslverr,   1'b0,  "setup pslverr u8");
            chk (prdata32,  32'd0, "setup prdata u32");
            chk1(pslverr32, 1'b0,  "setup pslverr u32");
        end
    endtask

    task apb_access;
        input        exp_err;
        input [31:0] exp8;
        input [31:0] exp32;
        input        chk32;
        begin
            @(negedge pclk);
            penable = 1'b1;
            #1;
            chk1(pready,    1'b1,    "pready u8");
            chk1(pready32,  1'b1,    "pready u32");
            chk1(pslverr,   exp_err, "pslverr u8");
            chk1(pslverr32, exp_err, "pslverr u32");
            chk (prdata,    exp8,    "prdata u8");
            if (chk32) chk(prdata32, exp32, "prdata u32");
        end
    endtask

    task apb_idle;
        begin
            @(negedge pclk);
            psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
            paddr = 8'd0; pwdata = 32'd0; pstrb = 4'd0;
            #1;
            chk (prdata,    32'd0, "idle prdata u8");
            chk1(pslverr,   1'b0,  "idle pslverr u8");
            chk (prdata32,  32'd0, "idle prdata u32");
            chk1(pslverr32, 1'b0,  "idle pslverr u32");
        end
    endtask

    task wr;
        input [7:0]  a;
        input [31:0] d;
        input [3:0]  s;
        input        err;
        begin
            apb_setup(a, 1'b1, d, s);
            apb_access(err, 32'd0, 32'd0, 1'b1);
            apb_idle;
        end
    endtask

    task rd;
        input [7:0]  a;
        input [31:0] exp8;
        input [31:0] exp32;
        input        chk32;
        input        err;
        begin
            apb_setup(a, 1'b0, 32'd0, 4'd0);
            apb_access(err, exp8, exp32, chk32);
            apb_idle;
        end
    endtask

    task wait_cyc;
        input integer n;
        begin
            repeat (n) @(negedge pclk);
        end
    endtask

    task rw_test;
        input [7:0] a;
        begin
            wr(a, 32'hFFFF_FFFF, 4'hF, 1'b0);
            rd(a, 32'h0000_00FF, 32'hFFFF_FFFF, 1'b1, 1'b0);
            wr(a, 32'h1234_5678, 4'h5, 1'b0);
            rd(a, 32'h0000_0078, 32'hFF34_FF78, 1'b1, 1'b0);
            wr(a, 32'h0000_0000, 4'h0, 1'b0);
            rd(a, 32'h0000_0078, 32'hFF34_FF78, 1'b1, 1'b0);
            wr(a, 32'h0000_0000, 4'h2, 1'b0);
            rd(a, 32'h0000_0078, 32'hFF34_0078, 1'b1, 1'b0);
            wr(a, 32'h0000_0000, 4'hF, 1'b0);
            rd(a, 32'h0000_0000, 32'h0000_0000, 1'b1, 1'b0);
        end
    endtask

    task rd_all_zero;
        input [31:0] din8;
        begin
            rd(A_DOUT, 32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_DIR,  32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_DIN,  din8,  32'd0, 1'b1, 1'b0);
            rd(A_RISE, 32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_FALL, 32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_HIGH, 32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_LOW,  32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_EN,   32'd0, 32'd0, 1'b1, 1'b0);
            rd(A_STAT, 32'd0, 32'd0, 1'b1, 1'b0);
        end
    endtask

    // ---------------- Test sequence ----------------
    initial begin
        passed = 0; failed = 0;
        presetn = 1'b0; psel = 1'b0; penable = 1'b0; pwrite = 1'b0;
        paddr = 8'd0; pwdata = 32'd0; pstrb = 4'd0;
        gin = 8'd0; gin32 = 32'd0;

        // ---- Reset ----
        wait_cyc(3);
        #1;
        chk ({24'd0, gout}, 32'd0, "reset gpio_out u8");
        chk ({24'd0, goe},  32'd0, "reset gpio_oe u8");
        chk1(irq,  1'b0,           "reset irq u8");
        chk (gout32, 32'd0,        "reset gpio_out u32");
        chk (goe32,  32'd0,        "reset gpio_oe u32");
        chk1(irq32, 1'b0,          "reset irq u32");
        presetn = 1'b1;
        rd_all_zero(32'd0);

        // ---- gpio_out / gpio_oe ----
        wr(A_DOUT, 32'h0000_00A5, 4'hF, 1'b0);
        chk({24'd0, gout}, 32'h0000_00A5, "gpio_out u8");
        chk(gout32, 32'h0000_00A5,        "gpio_out u32");
        wr(A_DIR, 32'hC300_005A, 4'hF, 1'b0);
        chk({24'd0, goe}, 32'h0000_005A,  "gpio_oe u8");
        chk(goe32, 32'hC300_005A,         "gpio_oe u32");
        wr(A_DOUT, 32'h0, 4'hF, 1'b0);
        wr(A_DIR,  32'h0, 4'hF, 1'b0);
        chk({24'd0, gout}, 32'd0, "gpio_out clr u8");
        chk({24'd0, goe},  32'd0, "gpio_oe clr u8");

        // ---- Read/write registers, partial strobes, bits above N ----
        rw_test(A_DOUT);
        rw_test(A_DIR);
        rw_test(A_RISE);
        rw_test(A_FALL);
        rw_test(A_HIGH);
        rw_test(A_LOW);   // low level with pins at 0 sets status (masked)
        rw_test(A_EN);

        // Status latched from the low-level phase; partial W1C.
        rd(A_STAT, 32'h0000_00FF, 32'hFFFF_FFFF, 1'b1, 1'b0);
        wr(A_STAT, 32'h0000_0F0F, 4'h2, 1'b0);
        rd(A_STAT, 32'h0000_00FF, 32'hFFFF_F0FF, 1'b1, 1'b0);
        wr(A_STAT, 32'h0000_000F, 4'h1, 1'b0);
        rd(A_STAT, 32'h0000_00F0, 32'hFFFF_F0F0, 1'b1, 1'b0);
        wr(A_STAT, 32'hFFFF_FFFF, 4'hF, 1'b0);
        rd(A_STAT, 32'd0, 32'd0, 1'b1, 1'b0);
        chk1(irq,   1'b0, "irq after clear u8");
        chk1(irq32, 1'b0, "irq after clear u32");

        // ---- PSLVERR policy ----
        wr(A_DOUT, 32'h0000_005A, 4'hF, 1'b0);
        wr(A_DIN,  32'hFFFF_FFFF, 4'hF, 1'b1);
        rd(A_DIN,  32'd0, 32'd0, 1'b1, 1'b0);
        wr(8'h01, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h22, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h24, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h40, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'h80, 32'hFFFF_FFFF, 4'hF, 1'b1);
        wr(8'hFC, 32'hFFFF_FFFF, 4'hF, 1'b1);
        rd(A_DOUT, 32'h0000_005A, 32'h0000_005A, 1'b1, 1'b0);
        chk({24'd0, gout}, 32'h0000_005A, "dout after bad wr");
        rd(8'h01, 32'd0, 32'd0, 1'b1, 1'b1);
        rd(8'h23, 32'd0, 32'd0, 1'b1, 1'b1);
        rd(8'h24, 32'd0, 32'd0, 1'b1, 1'b1);
        rd(8'h40, 32'd0, 32'd0, 1'b1, 1'b1);
        rd(8'hA0, 32'd0, 32'd0, 1'b1, 1'b1);
        wr(A_DOUT, 32'd0, 4'hF, 1'b0);

        // ---- DATA_IN ----
        @(negedge pclk);
        gin = 8'hA5; gin32 = 32'hDEAD_BEEF;
        wait_cyc(2);
        rd(A_DIN, 32'h0000_00A5, 32'hDEAD_BEEF, 1'b1, 1'b0);
        wr(A_DIR, 32'hFFFF_FFFF, 4'hF, 1'b0);
        rd(A_DIN, 32'h0000_00A5, 32'hDEAD_BEEF, 1'b1, 1'b0);
        wr(A_DIR, 32'd0, 4'hF, 1'b0);
        @(negedge pclk);
        gin = 8'h00; gin32 = 32'd0;
        wait_cyc(2);
        rd(A_DIN, 32'd0, 32'd0, 1'b1, 1'b0);

        // ---- Back-to-back transfers ----
        apb_setup(A_DOUT, 1'b1, 32'h0000_003C, 4'hF);
        apb_access(1'b0, 32'd0, 32'd0, 1'b1);
        apb_setup(A_DOUT, 1'b0, 32'd0, 4'd0);
        apb_access(1'b0, 32'h0000_003C, 32'h0000_003C, 1'b1);
        apb_setup(A_DIR, 1'b1, 32'h0000_000F, 4'h1);
        apb_access(1'b0, 32'd0, 32'd0, 1'b1);
        apb_setup(A_DIR, 1'b0, 32'd0, 4'd0);
        apb_access(1'b0, 32'h0000_000F, 32'h0000_000F, 1'b1);
        apb_idle;
        wr(A_DOUT, 32'd0, 4'hF, 1'b0);
        wr(A_DIR,  32'd0, 4'hF, 1'b0);

        // ---- Rising edge: fires once, partial clear ----
        wr(A_RISE, 32'h0000_0003, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h03;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0003, 32'd0, 1'b0, 1'b0);
        wait_cyc(3);
        rd(A_STAT, 32'h0000_0003, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0001, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0002, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0003, 4'h0, 1'b0);
        rd(A_STAT, 32'h0000_0002, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0002, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        wr(A_RISE, 32'd0, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);

        // ---- Falling edge ----
        wr(A_FALL, 32'h0000_0004, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h04;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0004, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0004, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        wr(A_FALL, 32'd0, 4'hF, 1'b0);

        // ---- High level: sets again after a clear ----
        wr(A_HIGH, 32'h0000_0008, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        @(negedge pclk); gin = 8'h08;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0008, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0008, 32'd0, 1'b0, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);
        wr(A_STAT, 32'h0000_0008, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        wr(A_HIGH, 32'd0, 4'hF, 1'b0);

        // ---- Low level ----
        wr(A_LOW, 32'h0000_0010, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0010, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0010, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0010, 32'd0, 1'b0, 1'b0);
        @(negedge pclk); gin = 8'h10;
        wait_cyc(2);
        wr(A_STAT, 32'h0000_0010, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        wr(A_LOW, 32'd0, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);

        // ---- Both edges and the interrupt mask ----
        wr(A_RISE, 32'h0000_0020, 4'hF, 1'b0);
        wr(A_FALL, 32'h0000_0020, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h20;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0020, 32'd0, 1'b0, 1'b0);
        chk1(irq, 1'b0, "irq masked rise");
        wr(A_STAT, 32'h0000_0020, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0020, 32'd0, 1'b0, 1'b0);
        chk1(irq, 1'b0, "irq masked fall");
        wr(A_EN, 32'h0000_0020, 4'hF, 1'b0);
        chk1(irq, 1'b1, "irq unmasked");
        wr(A_EN, 32'h0000_0010, 4'hF, 1'b0);
        chk1(irq, 1'b0, "irq other bit en");
        rd(A_STAT, 32'h0000_0020, 32'd0, 1'b0, 1'b0);
        wr(A_EN, 32'h0000_0020, 4'hF, 1'b0);
        chk1(irq, 1'b1, "irq re-enabled");
        wr(A_STAT, 32'h0000_0020, 4'hF, 1'b0);
        chk1(irq, 1'b0, "irq after w1c");
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        wr(A_RISE, 32'd0, 4'hF, 1'b0);
        wr(A_FALL, 32'd0, 4'hF, 1'b0);
        wr(A_EN,   32'd0, 4'hF, 1'b0);

        // ---- Detection beats a clear on the same edge ----
        wr(A_RISE, 32'h0000_0040, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h40;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0040, 32'd0, 1'b0, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0040, 32'd0, 1'b0, 1'b0);
        apb_setup(A_STAT, 1'b1, 32'h0000_0040, 4'hF);
        gin = 8'h40;               // sampled on the setup edge, detected on the access edge
        apb_access(1'b0, 32'd0, 32'd0, 1'b1);
        apb_idle;
        rd(A_STAT, 32'h0000_0040, 32'd0, 1'b0, 1'b0);
        wr(A_STAT, 32'h0000_0040, 4'hF, 1'b0);
        rd(A_STAT, 32'h0000_0000, 32'd0, 1'b0, 1'b0);
        wr(A_RISE, 32'd0, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h00;
        wait_cyc(2);

        // ---- Reset again with state present ----
        wr(A_DOUT, 32'h0000_00FF, 4'hF, 1'b0);
        wr(A_DIR,  32'h0000_00FF, 4'hF, 1'b0);
        wr(A_HIGH, 32'h0000_00FF, 4'hF, 1'b0);
        wr(A_EN,   32'h0000_00FF, 4'hF, 1'b0);
        @(negedge pclk); gin = 8'h81;
        wait_cyc(2);
        rd(A_STAT, 32'h0000_0081, 32'd0, 1'b0, 1'b0);
        chk1(irq, 1'b1, "irq before reset");
        @(negedge pclk); presetn = 1'b0;
        wait_cyc(2);
        #1;
        chk ({24'd0, gout}, 32'd0, "reset2 gpio_out u8");
        chk ({24'd0, goe},  32'd0, "reset2 gpio_oe u8");
        chk1(irq, 1'b0,            "reset2 irq u8");
        chk (gout32, 32'd0,        "reset2 gpio_out u32");
        chk (goe32,  32'd0,        "reset2 gpio_oe u32");
        chk1(irq32, 1'b0,          "reset2 irq u32");
        presetn = 1'b1;
        rd_all_zero(32'h0000_0081);
        chk1(irq, 1'b0, "irq after reset2");

        // ---- Verdict ----
        nonce = {8*64{1'b0}};
        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

